def eval_expr(s):
    """Evaluate an arithmetic expression string to a float.

    Supports non-negative integers, + - * /, parentheses, unary minus,
    and arbitrary whitespace. '/' is float division.
    Grammar: expr := term (('+'|'-') term)*
             term := unary (('*'|'/') unary)*
             unary := '-' unary | '+' unary | atom
             atom := '(' expr ')' | number
    """
    pos = 0
    n = len(s)

    def skip_ws():
        nonlocal pos
        while pos < n and s[pos].isspace():
            pos += 1

    def parse_expr():
        nonlocal pos
        val = parse_term()
        while True:
            skip_ws()
            if pos < n and s[pos] == '+':
                pos += 1
                val += parse_term()
            elif pos < n and s[pos] == '-':
                pos += 1
                val -= parse_term()
            else:
                return val

    def parse_term():
        nonlocal pos
        val = parse_unary()
        while True:
            skip_ws()
            if pos < n and s[pos] == '*':
                pos += 1
                val *= parse_unary()
            elif pos < n and s[pos] == '/':
                pos += 1
                val /= parse_unary()
            else:
                return val

    def parse_unary():
        nonlocal pos
        skip_ws()
        if pos < n and s[pos] == '-':
            pos += 1
            return -parse_unary()
        if pos < n and s[pos] == '+':
            pos += 1
            return parse_unary()
        return parse_atom()

    def parse_atom():
        nonlocal pos
        skip_ws()
        if pos < n and s[pos] == '(':
            pos += 1
            val = parse_expr()
            skip_ws()
            if pos >= n or s[pos] != ')':
                raise ValueError("expected ')'")
            pos += 1
            return val
        start = pos
        while pos < n and s[pos].isdigit():
            pos += 1
        if pos == start:
            raise ValueError("unexpected character")
        return float(s[start:pos])

    result = parse_expr()
    skip_ws()
    if pos != n:
        raise ValueError("trailing characters in expression")
    return float(result)
