def topo_count(n, edges):
    """Count distinct topological orderings of a DAG with nodes 0..n-1."""
    preds = [0] * n
    for u, v in edges:
        preds[v] |= 1 << u

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(mask):
        if mask == (1 << n) - 1:
            return 1
        total = 0
        for v in range(n):
            if not (mask >> v) & 1 and (preds[v] & mask) == preds[v]:
                total += dp(mask | (1 << v))
        return total

    return dp(0)
